                                 $scope.recordingState = {};
                                 var recognition = null;
                                 var activeIndex = null;
                                 var isFirstRecognitionChunk = true;
                                 $scope.initSpeechRecognition = function () {
                                     var SpeechRecognition =
                                         window.SpeechRecognition || window.webkitSpeechRecognition;
                                     if (!SpeechRecognition) {
                                         alert("Speech Recognition not supported");
                                         return;
                                     }
                                     recognition = new SpeechRecognition();
                                     recognition.lang = 'en-IN';
                                     recognition.continuous = true;
                                     recognition.interimResults = false;
                                     recognition.onresult = function (event) {
                                         var transcript = '';

                                         for (var i = event.resultIndex; i < event.results.length; i++) {
                                             if (event.results[i].isFinal) {
                                                 transcript += event.results[i][0].transcript;
                                             }
                                         }

                                         if (!transcript) return;

                                         if (isFirstRecognitionChunk) {
                                             transcript =
                                                 transcript.charAt(0).toUpperCase() + transcript.slice(1);
                                             isFirstRecognitionChunk = false;
                                         }

                                         $scope.$applyAsync(function () {
                                             if (angular.isNumber(activeIndex)) {

                                                 if (!$scope.dataListComplaints[activeIndex].remark) {
                                                     $scope.dataListComplaints[activeIndex].remark = transcript;
                                                 } else {
                                                     $scope.dataListComplaints[activeIndex].remark += ' ' + transcript;
                                                 }

                                             }
                                             else {

                                                 if (!$scope.complaintsUpdateObj.remark) {
                                                     $scope.complaintsUpdateObj.remark = transcript;
                                                 } else {
                                                     $scope.complaintsUpdateObj.remark += ' ' + transcript;
                                                 }

                                             }
                                         });
                                     };

                                     recognition.onend = function () {
                                         if (
                                             angular.isNumber(activeIndex)
                                                 ? $scope.recordingState[activeIndex]
                                                 : $scope.recordingState['single']
                                         ) {
                                             recognition.start();
                                         }
                                     };
                                 };

                                 $scope.initSpeechRecognition();
                                 $scope.startRecording = function (info, index) {

                                     var key = angular.isNumber(index) ? index : 'single';
                                     if (activeIndex === index) {
                                         $scope.recordingState[key] = false;
                                         activeIndex = null;
                                         recognition.stop();
                                         return;
                                     }
                                     if (activeIndex !== null) {
                                         var prevKey = angular.isNumber(activeIndex) ? activeIndex : 'single';
                                         $scope.recordingState[prevKey] = false;
                                         recognition.stop();
                                     }
                                     activeIndex = index;
                                     isFirstRecognitionChunk = true;
                                     $scope.recordingState[key] = true;

                                     try {
                                         recognition.start();
                                     } catch (e) {
                                         console.warn("Recognition already running");
                                     }
                                 };
