								   $scope.getListByName = function(name){
										
										var URI = BASE_URL + ROOT_URL +"/api/globals/items/item/search/"+name;
										
										return GenericService.serviceAction("GET",URI).then(function(response){
											if (!!response.data && response.data.length > 0)
													console.log("getListByName", response.data);
												return response.data;
											
											});
										
										}
								   
									$scope.selectImplant = function(info, model,label) {
										
										console.log(info);
										$scope.patientDetailsObj.itemId = info.itemId;
										$scope.patientDetailsObj.itemName = info.itemName;
										$scope.patientDetailsObj.kitId = info.kitId;
										$scope.implantObj.qty = info.qty;
										$scope.patientDetailsObj.kitName = info.kitName;
										$scope.patientDetailsObj.isItemOrKit = info.isItemOrKit;
										$scope.itemList.push(info);
										console.log("itemList", $scope.itemList);
									}
									
									$scope.saveImplantDetails = function() 
									{
										$scope.$broadcast('show-errors-check-validity');
											try {
												var date = new Date();
												$scope.dt = moment(date).format('DD-MM-YYYY HH:mm:ss');	
												
												$rootScope.startLoader();
												$scope.finalList = [];
									angular.forEach($scope.itemList, function(value , key) {
										
									 	var data = {
														
									 			itemId:value.itemId,
												kitId:value.kitId,
												patientId:$stateParams.patientDetailsObj.patientId,
												qty:value.qty,
												admissionId:$stateParams.patientDetailsObj.admissionId,
											     organizationId:$scope.organizationId,
											     unitId:$scope.unitId,
											     status:"A",
												 createdBy:$scope.userId,
												 createdDate:$scope.dt,
												 updatedBy:$scope.userId,
												 updatedDate:$scope.dt,
																}
														
									 	$scope.finalList.push(data);
									 				
			                     		});
											
										console.log("saveImplantDetails",$scope.finalList);
										/**/
										
										var URI = BASE_URL + ROOT_URL+"/api/otims/saveImplantdetails";
										
										 GenericService.serviceAction("POST", URI,$scope.finalList)
										.then(function(response) {	
											if (response.data.status == 'success')
											{
												$rootScope.stopLoader();
												growl.success(response.data.message,
														{
															title : 'Success!'
														});
												$scope.$broadcast('show-errors-reset');
											} else if(response.data.status == 'error')
											{
												$rootScope.stopLoader();
												growl.error(response.data.message,
														{
															title : 'Error!'
														});
											}
											
										});
									} catch (e) {
										console.log("Exception",e.message);
									}
									
							}
									
