                       $scope.validateTime=function(){
							var date = new Date();
							var time = moment().format("HH:mm");
							var currtime = moment(date).format('DD-MM-YYYY');
							var postFactoDate = moment($scope.postFactoDate).format('DD-MM-YYYY');
							
							var compareTime=$scope.postFactoTime+":00";
							var compareDate=moment($scope.postFactoDate+$scope.postFactoTime).format('DD-MM-YYYY HH:mm');
							
							if(currtime == postFactoDate)
								{
									 if( time  >= $scope.postFactoTime )
									 {
									 $scope.postFactoTime=$scope.postFactoTime;
									 }
								 else{
									 growl.warning("Time Should be equal or less than Current time.",
												{
													title : 'Warning!'
												});
										$scope.postFactoTime = time;
										return false;
								 }
								}
							else{
								 $scope.postFactoTime=$scope.postFactoTime;
							}
						}
