			$scope.saveFollowupAssesMentData = function(isDraft) {
				
             if(isDraft=="N"){
				if($scope.triage.selected==false && $scope.colors.selected==""){
					growl.warning("Enter Triage Category");
					return false;
			}

			if (
				$scope.vitalFollow.selected === false &&
				!$scope.vitals.bpSystolic &&
				!$scope.vitals.bpDiastolic &&
				!$scope.vitals.pulse &&
				!$scope.vitals.respiratoryRate &&
				!$scope.vitals.spo2 &&
				!$scope.vitals.temperature &&
				!$scope.vitals.oxygen &&
				!$scope.vitals.roomAir &&
				!$scope.vitals.pulseRegular &&
				!$scope.vitals.pulseIrregular
			  ) {
				growl.warning("Vital Signs Assessment");
				return false;
			  }


			  if($scope.airwayAssessment.selected===false && 
				!$scope.airway.selected&&
				!$scope.airwayAssessment.selected &&
				!$scope.suctionRequired.selected &&
				!$scope.airwayAdjunct.selected && 
				!$scope.suctionRequired.text 
			   ){
				growl.warning("Enter Airway Assessment");
				return false;
			   }

			  if($scope.breathing.selected===false && 
				!$scope.respiratoryEffort.selected &&
				!$scope.chestMovement.selected
			   ){
				growl.warning("Enter Breathing Assessment");
				return false;
			   }

			  if($scope.circulation.selected===false && 
				!$scope.skin.selected &&
				!$scope.capillaryRefill.selected
			   ){
				growl.warning("Enter Circulation Assessment");
				return false;
			   }

			  if($scope.neurological.selected===false && 
				!$scope.levelOfConsciousness.selected &&
				!$scope.pupils.selected
			   ){
				growl.warning("Enter Neurological Assessment");
				return false;
			   }

			  if($scope.symptom.selected===false && 
				!$scope.responseTreatment.selected &&
				!$scope.sideEffects.selected
			   ){
				growl.warning("Enter Pain & Symptom Assessment");
				return false;
			   }

			  if($scope.intake.selected===false && 
				!$scope.vomiting.selected &&
				!$scope.diarrhoea.selected
			   ){
				growl.warning("Enter Intake & Output");
				return false;
			   }

			  if($scope.investigations.selected===false && 
				!$scope.reports.selected 
			   ){
				growl.warning("Enter Investigations & Procedures");
				return false;
			   }

			  if($scope.escalation.selected===false && 
				!$scope.doctorInformed.selected &&
				!$scope.actionTaken.selected
			   ){
				growl.warning("Enter Early Warning & Escalation");
				return false;
			   }

			  if($scope.infection.selected===false && 
				!$scope.handHygiene.selected &&
				!$scope.fallRisk.selected
			   ){
				growl.warning("Enter Infection Control & Safety");
				return false;
			   }

			  if($scope.communication.selected===false && 
				!$scope.patientInformed.selected
			   ){
				growl.warning("Enter Communication & Education");
				return false;
			   }

			  if($scope.disposition.selected===false && 
				!$scope.currentCondition.selected &&
				!$scope.plan.selected
			   ){
				growl.warning("Enter Disposition Assessment");
				return false;
			   }
			 }

               
			 $scope.allData = $scope.collectFormData();
			 console.log("$scope.allData ",$scope.allData);
			 $rootScope.startLoader();
			//  $scope.totalGCSScore= $scope.abcde.disability.gcsTotal;
			var URI = BASE_URL + ROOT_URL + '/api/opd/saveFollowUpEassessment';
			$scope.assessmentStartTimeForSave = $scope.buildAssessmentDateTime($scope.assessmentStartTime)
			var data = {
				patientId: $scope.patientDetails.patientId,
				admissionId: $scope.patientDetails.admissionId,
				unitId: $scope.unitId,
				organizationId: $scope.organizationId,
				status: 'A',
				createdBy: $scope.userId,
				doctorId: $scope.doctorId,
				assessmentTime:$scope.assessmentStartTimeForSave,
				isDraft:isDraft,
				followUpAssessmentId:$scope.followUpAssessmentId,
				followUpAssessmentDesc: JSON.stringify($scope.allData) 
			};

			var paramObj = {}; 
			var headers = {}; 

			GenericServiceParamHeader
				.serviceAction(
					METHOD_POST,
					URI,
					data,
					NOTIFICATION_MSG_STATUS_FALSE,
					paramObj,
					headers
				)
				.then(
					function(response) {
						console.log("Save ABCDE Response:", response);
						if (response.data && response.data.status === "success") {
							if($scope.gcs.total!=null){
								// $scope.saveTotalGcsScaleScore();
								$scope.saveTotalGcsScaleScore();
							}

							if(isDraft=="N"){
								$scope.vitals.temperature;
                                 
								$scope.finalVitalForFollowUp.push({
									"vitalId":6,
									"value": $scope.vitals.temperature
								})

								$scope.finalVitalForFollowUp.push({
									"vitalId":4,
									"value": $scope.vitals.pulse
								})

								$scope.finalVitalForFollowUp.push({
									"vitalId":3,
									"value": $scope.vitals.bpSystolic
								})

								$scope.finalVitalForFollowUp.push({
									"vitalId":7,
									"value": $scope.vitals.bpDiastolic
								})

								$scope.finalVitalForFollowUp.push({
									"vitalId":10,
									"value": $scope.vitals.respiratoryRate
								})

								$scope.finalVitalForFollowUp.push({
									"vitalId":14,
									"value": $scope.vitals.spo2
								})

								
								


                                
								$scope.saveInitialAssessmentVitalsFolloUwp($scope.finalVitalForFollowUp);
							}
							growl.success(" Follow Up Assessment saved successfully.",
																	{
																	title : 'SUCCESS!'
																	});
																	$rootScope.stopLoader();
																		$scope.initFollowUpAssesmentForm();
																		// $scope.getFollowUpassessmentList();
																		$scope.getFollowUpAssessmentList();
					
						} else {
							console.error("Save failed:", response.data.message);
							growl.error("Failed to save Follow up Assessment.",
																	{
																	title : 'ERROR!'
																	});
							$rootScope.stopLoader();
								$scope.initFollowUpAssesmentForm();
								$scope.getFollowUpAssessmentList();
						}
					},
					function(error) {
						console.error("API error while saving ABCDE", error);
						growl.error("Failed to save Follow up Assessment.",
																	{
																	title : 'ERROR!'
																	});
																	$rootScope.stopLoader();
																	$scope.initFollowUpAssesmentForm();
																	$scope.getFollowUpAssessmentList();
					}
				);

		};

	
