$scope.bindSuctionText = function(fieldName) {
    var modelPath = $scope.modelMap[fieldName];
    if (!$scope.tempTranscript[fieldName] || !modelPath) return;

    // Split the path by dots and traverse the $scope object
    var pathParts = modelPath.split('.');
    var target = $scope;
    for (var i = 0; i < pathParts.length - 1; i++) {
        target = target[pathParts[i]];
        if (!target) return;
    }

    var lastKey = pathParts[pathParts.length - 1];
    target[lastKey] = (target[lastKey] || '') + $scope.tempTranscript[fieldName];

    $scope.tempTranscript[fieldName] = ''; // clear after binding
    $scope.$applyAsync();

    console.log("Bound transcript to", modelPath, ":", target[lastKey]);
};


