    $scope.validateFollowUpAssesementVitalData = function (vitalId,value,fromVitalOnly){
		
		
		console.log("vitalId:", vitalId);
		console.log("vitals.value  ",value);

		console.log("vital List : ",$scope.vitalsList);
		
		

		$scope.vitalDataVal = null;

	

		for (var i = 0; i < $scope.vitalsList.length; i++) {
			if ($scope.vitalsList[i].vitalId === vitalId) {
				$scope.vitalDataVal = $scope.vitalsList[i];
				break;
			}
		}
		
		console.log("Selected Vital Object:", $scope.vitalDataVal);
		if (!$scope.vitalDataVal) {
			return;
		}

		console.log("Selected Vital Object:", $scope.vitalDataVal);		
		
		$scope.vitalDataVal.vitalValue = value;
		
		
			if($scope.vitalDataVal.maxValue != null || $scope.vitalDataVal.minValue != null){

					if($scope.vitalDataVal.maxValue == null){
						$scope.vitalDataVal.maxValue = 0;
					}else if($scope.vitalDataVal.minValue == null){
						$scope.vitalDataVal.minValue = 0;
					}else if($scope.vitalDataVal.vitalValue == ""){
						growl.warning($scope.vitalDataVal.vitalName + " should be greater than " + $scope.vitalDataVal.minValue + "");
						$scope.disableVitalInput(vitalId,fromVitalOnly);
					}

					var max = Number($scope.vitalDataVal.maxValue);
					var min = Number($scope.vitalDataVal.minValue);
					var vitalVal = Number($scope.vitalDataVal.vitalValue);

					if(max < vitalVal){
						growl.warning($scope.vitalDataVal.vitalName + " should be less than " + max + "");
							$scope.vitalDataVal.vitalValue = "";
							$scope.disableVitalInput(vitalId,fromVitalOnly);
					}else if(min > vitalVal){
						growl.warning($scope.vitalDataVal.vitalName + " should be greater than " + min + "");
							$scope.vitalDataVal.vitalValue = "";
							$scope.disableVitalInput(vitalId,fromVitalOnly);
					}
				}



	}

	
